import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const v=JSON.parse('{"title":"Saves and recovery","description":"","frontmatter":{"pageId":"players/saves-recovery","contentRevision":6},"headers":[],"relativePath":"en/players/saves-recovery.md","filePath":"en/players/saves-recovery.md"}'),n={name:"en/players/saves-recovery.md"};function s(i,e,l,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="saves-and-recovery" tabindex="-1">Saves and recovery <a class="header-anchor" href="#saves-and-recovery" aria-label="Permalink to &quot;Saves and recovery&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><ol class="flow-diagram" aria-label="Process diagram"><li><strong>Stop</strong><span>Do not recreate the transfer.</span></li><li><strong>Preserve evidence</strong><span>Keep snapshot, upload and outbox.</span></li><li><strong>Rejoin</strong><span>Same account; original replay/server save.</span></li><li><strong>Verify outcome</strong><span>Map, status and mail; escalate refusals.</span></li></ol><p>The server holds the canonical save. Let normal saving and upload finish before leaving. Reconnect after a disconnect: unanswered operations are retried from the outbox with their original identifiers, not recreated.</p><p>In 0.8.1 recovery of unfinished deliveries is tied to an exact save snapshot. When recovery is offered, read the selected version and warnings. Do not load an arbitrary old local save to “recover” items already sent away.</p><p>If recovery cannot finish, preserve journals and give the administrator the server, time, save version and operation ID. An administrator can inspect versions and perform a controlled rollback.</p><h2 id="save-cycle" tabindex="-1">How are transfers and deliveries saved? <a class="header-anchor" href="#save-cycle" aria-label="Permalink to &quot;How are transfers and deliveries saved? {#save-cycle}&quot;">​</a></h2><p>A send follows: removal journal → exact home-map snapshot → server acceptance → original operation → result acknowledgement. Delivery is acknowledged only after a snapshot contains the received goods. Two saves on the same paused tick can still contain different state.</p><p>Login recovers an unfinished local snapshot before fetching mail. Do not grant returns just because a parcel still appears: the server may be awaiting evidence of delivery. Reconnection replays the original intent and ID, unlike a new request.</p><p>Normal return-to-menu lets saving finish. Killing the process is not a safe way to cancel a trade.</p><p>A new colony can be saved while paused before its first game tick. Tick zero comes from the game clock, independently of similarly named lists in event history. If upload is unfinished, preserve the original snapshot for recovery at login.</p><h2 id="recover-tree" tabindex="-1">Decision tree after a drop, rollback or reset <a class="header-anchor" href="#recover-tree" aria-label="Permalink to &quot;Decision tree after a drop, rollback or reset {#recover-tree}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Next action</th><th>Avoid</th></tr></thead><tbody><tr><td>Unknown transfer result</td><td>Rejoin with the same account, wait for replay, inspect result</td><td>Creating a duplicate transfer</td></tr><tr><td>Save predates the last transfer</td><td>Load the server-accepted version</td><td>Renaming an old file as current</td></tr><tr><td>Administrator rolled back</td><td>Return to menu, then sign in again</td><td>Writing from the cancelled map</td></tr><tr><td>Colony reset; old file separated</td><td>Load current server colony/start as instructed</td><td>Uploading <em>.reset-</em>.rws as a new version</td></tr><tr><td>Insufficient replay evidence</td><td>Preserve the folder and request help</td><td>Deleting journals to dismiss the dialog</td></tr></tbody></table><p>Keep pending-snapshot.json, upload-*.rws and outbox.json in <code>Saves/Rimlink/&lt;server&gt;_&lt;player&gt;</code>. Share time, operation ID and refusal text safely. These files may contain colony data; do not publish them. Rollback changes SaveWriteEpoch; reset changes SaveGeneration. Neither rewinds the entire settled server economy.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Never delete outbox or recovery journals based on an untrusted message. A rollback changes the colony timeline; it is not a rollback of the whole server economy.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./../admins/backup-recovery">Backup and recovery</a></li><li><a href="./troubleshooting">Player troubleshooting</a></li><li><a href="./economy">Wallet, mail and market</a></li></ul>',19)])])}const u=a(n,[["render",s]]);export{v as __pageData,u as default};
